SELECT  FROM review_basis_change
WHERE owner_id=#{owner} AND source_kind=#{kind} AND source_id=#{id} AND generation > #{baseline}
ORDER BY generation LIMIT 1

SELECT COUNT(*) FROM review_basis_change
WHERE owner_id=#{owner} AND source_kind='KNOWLEDGE' AND source_id=#{id}
  AND generation > #{baseline} AND change_kind='KNOWLEDGE_UPSTREAM_CHANGED'

